cd /code && python - <<'PY'
from bs4 import BeautifulSoup
html=open('../results/FS-Filters.html').read()
soup=BeautifulSoup(html,'html.parser')
# find code cell containing print(best_k,best_acc)
for pre in soup.find_all('pre'):
    txt=pre.get_text('\n')
    if 'print(best_k, best_acc)' in txt:
        print('FOUND CODE CELL')
        parent=pre.parent
        # print following siblings text maybe outputs in same cell container
        for sib in parent.next_siblings:
            if getattr(sib,'name',None):
                t=sib.get_text('\n', strip=True)
                if t:
                    print('SIB', sib.name, t[:500])
                if sib.name=='div' and 'output' in sib.get('class',[]):
                    pass
        break
# search for output text containing just numbers
for string in soup.stripped_strings:
    if string.strip()=='0.9180451127819549' or string.strip()=='0.92':
        print('match',string)
